-- TOPTROOPS(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _tksqfm = 115
local _otpung = 69
local _pjgbzz = 81
local _cmxkrb = ""

local _bvlcon = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _mjhisb(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _jhsvfu(d)
	d = d:gsub("[^" .. _bvlcon .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_bvlcon:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _zvnbmp = _jhsvfu(_cmxkrb)
local _ytkqni = { _tksqfm, _otpung, _pjgbzz }
local _qdmbsp = {}
for i = 1, #_zvnbmp do
	_qdmbsp[i] = string.char(_mjhisb(_zvnbmp:byte(i), _ytkqni[(i - 1) % 3 + 1]))
end

local _pynhls = load or loadstring
local _jrwtfp, _tyxrex = _pynhls(table.concat(_qdmbsp), "=w")
if not _jrwtfp then
	gg.alert("Corrupted file: " .. tostring(_tyxrex))
	os.exit()
end
_jrwtfp()
